package com.ddarungflow.station; import com.ddarungflow.dto.StationRhythmDtos; import com.ddarungflow.repository.StationRhythmProfileRepository; import com.fasterxml.jackson.databind.*; import org.springframework.stereotype.Service;
@Service public class StationRhythmService { private final StationRhythmProfileRepository repository; private final ObjectMapper mapper; public StationRhythmService(StationRhythmProfileRepository repository,ObjectMapper mapper){this.repository=repository;this.mapper=mapper;} public StationRhythmDtos.Response find(String id){var p=repository.findById(id).orElseThrow(NotFound::new); try { JsonNode payload=mapper.readTree(p.getPayload()); return new StationRhythmDtos.Response(p.getWindowStart(),p.getWindowEnd(),p.getSampleCount(),payload.path("weekdayHourly"),payload.path("stockout")); }catch(Exception e){throw new IllegalStateException(e);} } public static class NotFound extends RuntimeException{} }
